function classify(a: int, b: int, c: int): int { return a * 100 + b * 10 + c; }
function pick(flag: boolean, yes: string, no: string): string { if (flag) { return yes; } return no; }
export function test(): int {
  let i: int = classify(3, 2, 1);
  let s: string = pick(true, "jvm", "lua");
  if (s === "jvm") { return i; }
  return 0;
}

function double(x: int): int { return x * 2; }
function add(a: int, b: int): int { return a + b; }
export function test(): int {
  let a: int = double(21);
  let b: int = add(a, a);
  return b;
}

function inc(x: int): int { return x + 1; }
function add(a: int, b: int): int { return a + b; }
export function test(): int { return add(inc(inc(1)), inc(inc(inc(2)))); }

function fact(n: int): int {
  if (n <= 1) { return 1; }
  return n * fact(n - 1);
}
export function test(): int { return fact(6); }

function fib(n: int): int {
  if (n <= 1) { return n; }
  return fib(n - 1) + fib(n - 2);
}
export function test(): int { return fib(10); }

